#include <iostream>
#include <string>
#include <iomanip>
#include <cstdint>

// Mô hình hóa Field và Record trong C++ hiện đại
// Modeling Fields and Records in modern C++
struct EmployeeRecord {
    std::uint32_t id;      // Field: số nguyên (whole number)
    std::string name;      // Field: chuỗi ký tự (character string)
    double hourlyRate;     // Field: số dấu phẩy động (decimal point)
    double hoursWorked;    // Field: số giờ làm việc
};

int main() {
    // Khởi tạo một bản ghi (Record)
    EmployeeRecord emp{101, "Judy Green", 28.50, 40.0};

    // Tính toán dựa trên các trường (Fields)
    double grossPay = emp.hourlyRate * emp.hoursWorked;

    // Xuất thông tin bản ghi
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Record ID: " << emp.id << "\n";
    std::cout << "Name: " << emp.name << "\n";
    std::cout << "Gross Pay: $" << grossPay << "\n";

    // Minh họa kích thước đơn vị dữ liệu cơ bản
    std::cout << "Size of char (1 byte / 8 bits): " << sizeof(char) << " byte\n";
    std::cout << "Size of uint32_t: " << sizeof(std::uint32_t) << " bytes\n";

    return 0;
}

#include <iostream>

// Trong ngôn ngữ bậc cao C++, phép tính lương được diễn đạt rõ ràng:
// In a high-level language like C++, payroll calculation is expressed directly:
// grossPay = basePay + overTimePay;

double computeGrossPay(double basePay, double overTimePay) {
    return basePay + overTimePay;
}

int main() {
    double basePay = 800.00;
    double overTimePay = 250.50;

    // Lời gọi hàm cấp cao được trình biên dịch (compiler) hạ cấp xuống 
    // các lệnh máy / thanh ghi của CPU.
    double grossPay = computeGrossPay(basePay, overTimePay);

    std::cout << "Base Pay: $" << basePay << "\n";
    std::cout << "Overtime Pay: $" << overTimePay << "\n";
    std::cout << "Gross Pay: $" << grossPay << "\n";

    return 0;
}
